function getStoredUser(): DemoUser | null {
  try { return JSON.parse(localStorage.getItem("mindsaathi_user") || "null"); } catch { return null; }
}
function setStoredUser(user: DemoUser | null) { if (user) localStorage.setItem("mindsaathi_user", JSON.stringify(user)); else localStorage.removeItem("mindsaathi_user"); }
function initials(name = "MindSaathi") { return name.split(" ").map(part => part[0]).join("").slice(0, 2).toUpperCase(); }
function formatDate(value: string) { return new Date(value).toLocaleDateString(undefined, { day: "numeric", month: "short" }); }
function formatTime(value: string) { return new Date(value).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" }); }
function typeLabel(type: ActivityType) { return activityMeta[type]?.title ?? type; }

function Logo({ compact = false }: { compact?: boolean }) {
  return <img src={LOGO_IMAGE} alt="MindSaathi" className={`${compact ? "h-14 w-[86px]" : "h-16 w-[110px]"} shrink-0 object-contain mix-blend-multiply`} />;
}

function Button({ children, variant = "primary", className = "", onClick, type = "button", disabled = false }: { children: React.ReactNode; variant?: "primary" | "outline" | "soft" | "ghost"; className?: string; onClick?: () => void; type?: "button" | "submit"; disabled?: boolean }) {
  const styles = { primary: "bg-[#4f9a63] text-white hover:bg-[#438955] shadow-[0_8px_18px_rgba(79,154,99,.18)]", outline: "border border-[#123e63] bg-white text-[#123e63] hover:bg-[#eaf3fa]", soft: "bg-[#eaf5ec] text-[#2f7043] hover:bg-[#dff0e3]", ghost: "text-[#6b7c8f] hover:bg-[#f3f6f7] hover:text-[#123e63]" };
  return <button type={type} disabled={disabled} onClick={onClick} className={`button-press inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-5 text-sm font-bold transition disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`}>{children}</button>;
}

